use std::collections::HashMap;
use std::hash::Hash;
use std::time::{Duration, Instant};

/// A single page of results returned by cursor-based pagination.
#[derive(Debug, Clone, PartialEq)]
pub struct Page<T> {
    /// The items in this page.
    pub items: Vec<T>,
    /// Opaque cursor pointing to the next page, if one exists.
    pub next_cursor: Option<String>,
}

/// Entry stored in the cache with an expiration timestamp.
#[derive(Debug, Clone)]
struct CacheEntry<T: Clone> {
    page: Page<T>,
    expires_at: Instant,
}

/// A paginated cache that stores pages keyed by cursor with a per-entry TTL.
///
/// `cache_with_ttl` returns a page of items from `data` using cursor-based
/// pagination.  Results are cached so that repeated requests for the same
/// cursor return the cached page as long as it has not expired.
///
/// - `data`      – the full list of items to paginate.
/// - `cursor`    – an opaque cursor (use `None` for the first page).
/// - `page_size` – maximum number of items per page (must be > 0).
/// - `ttl`       – how long a cached page remains valid.
///
/// Returns `None` if the cursor is invalid (out-of-range or malformed).
pub fn cache_with_ttl<T: Clone + Eq + Hash>(
    data: &[T],
    cache: &mut HashMap<String, CacheEntry<T>>,
    cursor: Option<&str>,
    page_size: usize,
    ttl: Duration,
) -> Option<Page<T>> {
    if page_size == 0 {
        return None;
    }

    let cursor_key = cursor.unwrap_or("").to_string();

    // Return cached page if still valid.
    if let Some(entry) = cache.get(&cursor_key) {
        if Instant::now() < entry.expires_at {
            return Some(entry.page.clone());
        }
        cache.remove(&cursor_key);
    }

    // Parse cursor into an offset.
    let offset = match cursor {
        None => 0,
        Some(s) => s.parse::<usize>().ok()?,
    };

    if offset > data.len() {
        return None;
    }

    let end = (offset + page_size).min(data.len());
    let items = data[offset..end].to_vec();
    let next_cursor = if end < data.len() {
        Some(end.to_string())
    } else {
        None
    };

    let page = Page {
        items,
        next_cursor: next_cursor.clone(),
    };

    cache.insert(
        cursor_key,
        CacheEntry {
            page: page.clone(),
            expires_at: Instant::now() + ttl,
        },
    );

    Some(page)
}

/// Drain all pages from a dataset using the cache, returning all items in order.
pub fn drain_all<T: Clone + Eq + Hash>(
    data: &[T],
    cache: &mut HashMap<String, CacheEntry<T>>,
    page_size: usize,
    ttl: Duration,
) -> Vec<T> {
    let mut all = Vec::new();
    let mut cursor: Option<String> = None;

    loop {
        let page = cache_with_ttl(
            data,
            cache,
            cursor.as_deref(),
            page_size,
            ttl,
        );

        match page {
            Some(p) => {
                all.extend(p.items);
                match p.next_cursor {
                    Some(c) => cursor = Some(c),
                    None => break,
                }
            }
            None => break,
        }
    }

    all
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::thread;

    fn empty_cache() -> HashMap<String, CacheEntry<i32>> {
        HashMap::new()
    }

    fn long_ttl() -> Duration {
        Duration::from_secs(60)
    }

    fn short_ttl() -> Duration {
        Duration::from_millis(50)
    }

    // ── Basic pagination ──────────────────────────────────────────────

    #[test]
    fn first_page_returns_correct_items() {
        let data: Vec<i32> = (0..10).collect();
        let mut cache = empty_cache();

        let page = cache_with_ttl(&data, &mut cache, None, 3, long_ttl()).unwrap();
        assert_eq!(page.items, vec![0, 1, 2]);
        assert_eq!(page.next_cursor.as_deref(), Some("3"));
    }

    #[test]
    fn second_page_returns_next_items() {
        let data: Vec<i32> = (0..10).collect();
        let mut cache = empty_cache();

        let page = cache_with_ttl(&data, &mut cache, Some("3"), 3, long_ttl()).unwrap();
        assert_eq!(page.items, vec![3, 4, 5]);
        assert_eq!(page.next_cursor.as_deref(), Some("6"));
    }

    #[test]
    fn last_page_has_no_next_cursor() {
        let data: Vec<i32> = (0..5).collect();
        let mut cache = empty_cache();

        let page = cache_with_ttl(&data, &mut cache, Some("3"), 3, long_ttl()).unwrap();
        assert_eq!(page.items, vec![3, 4]);
        assert_eq!(page.next_cursor, None);
    }

    #[test]
    fn page_size_larger_than_data_returns_all() {
        let data: Vec<i32> = vec![1, 2, 3];
        let mut cache = empty_cache();

        let page = cache_with_ttl(&data, &mut cache, None, 100, long_ttl()).unwrap();
        assert_eq!(page.items, vec![1, 2, 3]);
        assert_eq!(page.next_cursor, None);
    }

    #[test]
    fn empty_data_returns_empty_page() {
        let data: Vec<i32> = vec![];
        let mut cache = empty_cache();

        let page = cache_with_ttl(&data, &mut cache, None, 5, long_ttl()).unwrap();
        assert!(page.items.is_empty());
        assert_eq!(page.next_cursor, None);
    }

    #[test]
    fn exact_page_boundary_has_no_next_cursor() {
        let data: Vec<i32> = (0..6).collect();
        let mut cache = empty_cache();

        let page = cache_with_ttl(&data, &mut cache, Some("3"), 3, long_ttl()).unwrap();
        assert_eq!(page.items, vec![3, 4, 5]);
        assert_eq!(page.next_cursor, None);
    }

    // ── Invalid inputs ────────────────────────────────────────────────

    #[test]
    fn zero_page_size_returns_none() {
        let data: Vec<i32> = (0..5).collect();
        let mut cache = empty_cache();

        assert!(cache_with_ttl(&data, &mut cache, None, 0, long_ttl()).is_none());
    }

    #[test]
    fn invalid_cursor_returns_none() {
        let data: Vec<i32> = (0..5).collect();
        let mut cache = empty_cache();

        assert!(cache_with_ttl(&data, &mut cache, Some("abc"), 3, long_ttl()).is_none());
    }

    #[test]
    fn cursor_beyond_data_returns_none() {
        let data: Vec<i32> = (0..5).collect();
        let mut cache = empty_cache();

        assert!(cache_with_ttl(&data, &mut cache, Some("100"), 3, long_ttl()).is_none());
    }

    #[test]
    fn negative_cursor_returns_none() {
        let data: Vec<i32> = (0..5).collect();
        let mut cache = empty_cache();

        assert!(cache_with_ttl(&data, &mut cache, Some("-1"), 3, long_ttl()).is_none());
    }

    // ── Cache hit / miss ──────────────────────────────────────────────

    #[test]
    fn repeated_request_returns_cached_page() {
        let data: Vec<i32> = (0..10).collect();
        let mut cache = empty_cache();

        let p1 = cache_with_ttl(&data, &mut cache, None, 3, long_ttl()).unwrap();
        let p2 = cache_with_ttl(&data, &mut cache, None, 3, long_ttl()).unwrap();

        assert_eq!(p1, p2);
        // Only one entry in the cache.
        assert_eq!(cache.len(), 1);
    }

    #[test]
    fn different_cursors_produce_different_cache_entries() {
        let data: Vec<i32> = (0..10).collect();
        let mut cache = empty_cache();

        cache_with_ttl(&data, &mut cache, None, 3, long_ttl()).unwrap();
        cache_with_ttl(&data, &mut cache, Some("3"), 3, long_ttl()).unwrap();
        cache_with_ttl(&data, &mut cache, Some("6"), 3, long_ttl()).unwrap();

        assert_eq!(cache.len(), 3);
    }

    // ── TTL expiration ────────────────────────────────────────────────

    #[test]
    fn expired_entry_is_refreshed() {
        let data: Vec<i32> = (0..10).collect();
        let mut cache = empty_cache();

        let p1 = cache_with_ttl(&data, &mut cache, None, 3, short_ttl()).unwrap();
        assert_eq!(p1.items, vec![0, 1, 2]);

        thread::sleep(Duration::from_millis(80));

        // Should miss cache and return fresh data.
        let p2 = cache_with_ttl(&data, &mut cache, None, 3, short_ttl()).unwrap();
        assert_eq!(p2.items, vec![0, 1, 2]);
    }

    #[test]
    fn unexpired_entry_still_served() {
        let data: Vec<i32> = (0..10).collect();
        let mut cache = empty_cache();

        let p1 = cache_with_ttl(&data, &mut cache, None, 3, long_ttl()).unwrap();
        thread::sleep(Duration::from_millis(20));

        let p2 = cache_with_ttl(&data, &mut cache, None, 3, long_ttl()).unwrap();
        assert_eq!(p1, p2);
    }

    // ── drain_all ─────────────────────────────────────────────────────

    #[test]
    fn drain_all_returns_every_item_in_order() {
        let data: Vec<i32> = (0..10).collect();
        let mut cache = empty_cache();

        let all = drain_all(&data, &mut cache, 3, long_ttl());
        assert_eq!(all, data);
    }

    #[test]
    fn drain_all_with_page_size_one() {
        let data: Vec<i32> = vec![10, 20, 30];
        let mut cache = empty_cache();

        let all = drain_all(&data, &mut cache, 1, long_ttl());
        assert_eq!(all, vec![10, 20, 30]);
    }

    #[test]
    fn drain_all_single_page() {
        let data: Vec<i32> = vec![1, 2];
        let mut cache = empty_cache();

        let all = drain_all(&data, &mut cache, 10, long_ttl());
        assert_eq!(all, vec![1, 2]);
    }

    #[test]
    fn drain_all_empty_data() {
        let data: Vec<i32> = vec![];
        let mut cache = empty_cache();

        let all = drain_all(&data, &mut cache, 5, long_ttl());
        assert!(all.is_empty());
    }

    // ── Generic type support ──────────────────────────────────────────

    #[test]
    fn works_with_strings() {
        let data: Vec<String> = vec!["a", "b", "c", "d"]
            .into_iter()
            .map(String::from)
            .collect();
        let mut cache: HashMap<String, CacheEntry<String>> = HashMap::new();

        let page = cache_with_ttl(&data, &mut cache, None, 2, long_ttl()).unwrap();
        assert_eq!(page.items, vec!["a".to_string(), "b".to_string()]);
        assert_eq!(page.next_cursor.as_deref(), Some("2"));

        let page2 = cache_with_ttl(&data, &mut cache, Some("2"), 2, long_ttl()).unwrap();
        assert_eq!(page2.items, vec!["c".to_string(), "d".to_string()]);
        assert_eq!(page2.next_cursor, None);
    }

    #[test]
    fn works_with_tuples() {
        let data: Vec<(i32, &str)> = vec![(1, "a"), (2, "b"), (3, "c")];
        let mut cache: HashMap<String, CacheEntry<(i32, &str)>> = HashMap::new();

        let page = cache_with_ttl(&data, &mut cache, None, 2, long_ttl()).unwrap();
        assert_eq!(page.items, vec![(1, "a"), (2, "b")]);
    }

    // ── Cursor stability ──────────────────────────────────────────────

    #[test]
    fn cursor_from_page_can_be_used_for_next_request() {
        let data: Vec<i32> = (0..9).collect();
        let mut cache = empty_cache();

        let p1 = cache_with_ttl(&data, &mut cache, None, 3, long_ttl()).unwrap();
        let cursor = p1.next_cursor.unwrap();

        let p2 = cache_with_ttl(&data, &mut cache, Some(&cursor), 3, long_ttl()).unwrap();
        assert_eq!(p2.items, vec![3, 4, 5]);

        let cursor2 = p2.next_cursor.unwrap();
        let p3 = cache_with_ttl(&data, &mut cache, Some(&cursor2), 3, long_ttl()).unwrap();
        assert_eq!(p3.items, vec![6, 7, 8]);
        assert_eq!(p3.next_cursor, None);
    }

    #[test]
    fn full_traversal_via_cursor_chain() {
        let data: Vec<i32> = (0..7).collect();
        let mut cache = empty_cache();

        let mut all = Vec::new();
        let mut cursor: Option<String> = None;

        loop {
            let page = cache_with_ttl(
                &data,
                &mut cache,
                cursor.as_deref(),
                2,
                long_ttl(),
            )
            .unwrap();

            all.extend(page.items);
            match page.next_cursor {
                Some(c) => cursor = Some(c),
                None => break,
            }
        }

        assert_eq!(all, data);
    }

    // ── Edge: single-element data ─────────────────────────────────────

    #[test]
    fn single_element_data() {
        let data: Vec<i32> = vec![42];
        let mut cache = empty_cache();

        let page = cache_with_ttl(&data, &mut cache, None, 5, long_ttl()).unwrap();
        assert_eq!(page.items, vec![42]);
        assert_eq!(page.next_cursor, None);
    }
}

